/// <summary>
/// The service class for updating sales order invoice integration staus.
/// </summary>
class METUpdateSalesInvoiceIntegrationStatusService extends SysOperationServiceBase
{
}

Method.Source:
    /// <summary>
    /// Updates the sales order invoice integration status.
    /// </summary>
    /// <param name="_contract">
    /// The <C>METUpdateSalesInvoiceIntegrationStatusCollectionContract</C> instance
    /// </param>
    /// <returns>reponse as a data contract <c>METUpdateSalesInvoiceIntegrationStatusResponseCollectionContract</c> </returns>
    public METUpdateSalesInvoiceIntegrationStatusResponseCollectionContract updateSOIntegrationStatus(METUpdateSalesInvoiceIntegrationStatusCollectionContract _contract)
    {
        CustInvoiceJour     custInvoiceJour;
        InvoiceId           invoiceId;
        CustAccount         custAccount;
        METCustInvoiceJour  metCustInvoiceJour;
        METUpdateSalesInvoiceIntegrationStatusContract  requestContract;
        List                                 responseList = new List(Types::Class);
        METUpdateSalesInvoiceIntegrationStatusResponseCollectionContract response = new METUpdateSalesInvoiceIntegrationStatusResponseCollectionContract();
        ListEnumerator      customerInvoicesListEnumerator = _contract.parmCustomerInvoicesList().getEnumerator();


        #OCCRetryCount
        
        changecompany(_contract.parmDataAreaId())
        {
            while(customerInvoicesListEnumerator.moveNext())
            {
                METUpdateSalesInvoiceIntegrationStatusResponseContract updateResponse = new METUpdateSalesInvoiceIntegrationStatusResponseContract();
                requestContract = customerInvoicesListEnumerator.current();
                try
                {
                    invoiceId = requestContract.parmInvoiceId();
                    custAccount = requestContract.parmCustAccount();

                    select firstonly RecId from custInvoiceJour
                        join RecId from metCustInvoiceJour
                            where custInvoiceJour.InvoiceId == invoiceId
                                && custInvoiceJour.InvoiceAccount == custAccount
                                && metCustInvoiceJour.CustInvoiceJour == custInvoiceJour.RecId;

                    if(metCustInvoiceJour.RecId)
                    {
                        ttsbegin;
                        metCustInvoiceJour.selectForUpdate(true);
                        metCustInvoiceJour.IntegrationStatus = METIntegrationStatus::Acknowledged;
                        metCustInvoiceJour.doUpdate();
                        ttscommit;
                    }
                    updateResponse.parmSuccess(NoYes::Yes);
                    updateResponse.parmMessage("@MET:SalesInvoiceUpdateSuccessful");
                    updateResponse.parmCustAccount(invoiceId);
                    updateResponse.parmInvoiceId(custAccount);
                }
                catch(Exception::Deadlock)
                {
                    if (xSession::currentRetryCount() >= #RetryNum)
                    {
                        updateResponse.parmSuccess(NoYes::No);
                        updateResponse.parmMessage("@MET:SalesInvoiceUpdateFailedDatabaseDeadlock");
                        updateResponse.parmCustAccount(invoiceId);
                        updateResponse.parmInvoiceId(custAccount);
                        throw Exception::Error;
                    }
                    else
                    {
                        retry;
                    }
                }
                catch(Exception::UpdateConflict)
                {
                    if (appl.ttsLevel() == 0)
                    {
                        if (xSession::currentRetryCount() >= #RetryNum)
                        {
                            throw Exception::UpdateConflictNotRecovered;
                        }
                        else
                        {
                            retry;
                        }
                    }
                    else
                    {
                        updateResponse.parmSuccess(NoYes::No);
                        updateResponse.parmMessage("@MET:SalesInvoiceUpdateFailedDatabaseConflict");
                        updateResponse.parmCustAccount(invoiceId);
                        updateResponse.parmInvoiceId(custAccount);
                        throw Exception::UpdateConflict;
                    }
                }
                catch(Exception::CLRError)
                {
                    System.Exception interopException = CLRInterop::getLastException();
                    updateResponse.parmSuccess(NoYes::No);
                    updateResponse.parmMessage(interopException.ToString());
                    updateResponse.parmCustAccount(invoiceId);
                    updateResponse.parmInvoiceId(custAccount);
                }
                catch(Exception::Error)
                {
                    updateResponse.parmSuccess(NoYes::No);
                    updateResponse.parmMessage("@MET:SalesInvoiceUpdateFailed");
                    updateResponse.parmCustAccount(invoiceId);
                    updateResponse.parmInvoiceId(custAccount);
                }

                responseList.addEnd(updateResponse);
            }
        }

        response.parmCustomerInvoiceIntegrationStatusResponseList(responseList);
        return response;
    }
